import React,{createContext,useContext,useEffect,useState,useCallback} from 'react';
import {BrowserRouter,Routes,Route,NavLink,Link,Navigate,useNavigate,useLocation,useSearchParams} from 'react-router-dom';
import {API,api,setToken} from './api.js';
import {Icon,MotionBackground,Guide,LetterFeedback} from './Animation.jsx';
import {ServiceArt,SolJourney,StateGuide} from './ServiceArt.jsx';
const Auth=createContext(null);
const money=n=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(Number(n||0));
const date=d=>d?new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Lima'}).format(new Date(d)):'—';
const rol=u=>u?.roles?.find(r=>r.modulo==='sunat')?.rol;
const isStaff=u=>['empleado','administrador'].includes(rol(u));
function useLoad(path){const [state,set]=useState({loading:true,data:null,error:''});const [v,refresh]=useState(0);useEffect(()=>{let active=true;set(s=>({...s,loading:true,error:''}));api(path).then(data=>active&&set({loading:false,data,error:''})).catch(e=>active&&set({loading:false,data:null,error:e.message}));return()=>{active=false;};},[path,v]);return {...state,reload:()=>refresh(x=>x+1)};}
function ErrorMessage({text}){return text?<div className="alert alert-danger" role="alert">{text}</div>:null;}
function Notice({text}){return text?<div className="alert alert-success" role="status"><Icon name="check"/> {text}</div>:null;}
function Load({state,children}){return state.loading?<div className="loading-state" role="status"><span className="spinner-border spinner-border-sm"/> Cargando tus datos…</div>:state.error?<ErrorMessage text={state.error}/>:children(state.data);}
function Empty({text='Todavía no hay registros.'}){return <div className="empty-state"><Icon name="document" size={34}/><p>{text}</p></div>;}
function Asset({name,alt,...props}){const [error,setError]=useState(false);return error?<div className="asset-placeholder"><Icon name="shield" size={60}/></div>:<img src={API+'/publico/imagenes/'+name} alt={alt} onError={()=>setError(true)} {...props}/>;}
function Field({label,name,children,...props}){return <div className="field"><label htmlFor={'field-'+name}>{label}</label>{children||<input className="form-control" id={'field-'+name} name={name} required {...props}/>}</div>;}
function Select({label,name,children,...props}){return <div className="field"><label htmlFor={'field-'+name}>{label}</label><select id={'field-'+name} className="form-select" name={name} {...props}>{children}</select></div>;}
function Badge({state}){return <span className={'status-badge status-'+String(state).replaceAll(' ','-')}><i/>{state}</span>;}
function Title({eyebrow='MI CUENTA',title,sub,children}){return <div className="page-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{sub&&<p>{sub}</p>}</div>{children}</div>;}
function ScrollTop(){const loc=useLocation();useEffect(()=>{window.scrollTo({top:0,behavior:'instant'});},[loc.pathname]);return null;}
export function App(){const [user,setUser]=useState(null),[loading,setLoading]=useState(true);useEffect(()=>{api('/auth/me').then(setUser).catch(()=>setToken(null)).finally(()=>setLoading(false));},[]);return <Auth.Provider value={{user,setUser}}><BrowserRouter><ScrollTop/><Layout loading={loading}/></BrowserRouter></Auth.Provider>;}
function Private({children,roles}){const {user}=useContext(Auth);return !user?<Navigate to="/login" replace/>:roles&&!roles.includes(rol(user))?<Navigate to="/cuenta" replace/>:children;}
function Layout({loading}){const {user,setUser}=useContext(Auth);const [menu,setMenu]=useState(false),[connected,setConnected]=useState(null);const location=useLocation();useEffect(()=>{setMenu(false);},[location.pathname]);useEffect(()=>{api('/salud').then(()=>setConnected(true)).catch(()=>setConnected(false));},[]);const logout=()=>{setToken(null);setUser(null);};return <><a className="skip-link" href="#main">Saltar al contenido</a><div className="topbar"><div className="container d-flex justify-content-between"><span>Servicios tributarios digitales</span><span className={'service-status '+(connected?'online':'')}><i/>{connected===null?'Conectando…':connected?'Servicio disponible':'Servicio no disponible'}</span></div></div><header className="public-header"><div className="container header-inner"><Link className="brand" to="/"><Asset name="sunat-isotipo" alt="" className="brand-logo"/><span>SUNAT<small>PERÚ</small></span></Link><button className="mobile-menu" aria-label="Abrir menú" aria-expanded={menu} onClick={()=>setMenu(!menu)}><Icon name="menu"/></button><nav className={'public-nav '+(menu?'open':'')} aria-label="Navegación principal">{[['/','Inicio'],['/servicios','Servicios'],['/clave-sol','Clave SOL'],['/como-funciona','Cómo solicitar'],['/contacto','Contacto']].map(([to,label])=><NavLink key={to} to={to} end={to==='/'}>{label}</NavLink>)}</nav><Link className="btn btn-sunat header-account" to={user?'/cuenta':'/login'}><Icon name="user" size={17}/>{user?'Mi cuenta':'Ingresar'}</Link></div></header>{loading?<div className="loading-state">Preparando tu espacio…</div>:<main id="main"><Routes><Route path="/" element={<Home/>}/><Route path="/servicios" element={<Services/>}/><Route path="/clave-sol" element={<ClaveInfo/>}/><Route path="/como-funciona" element={<GuidePage/>}/><Route path="/cronograma" element={<Agenda/>}/><Route path="/contacto" element={<Contact/>}/><Route path="/login" element={<Login/>}/><Route element={<Private><AccountShell/></Private>}><Route path="/cuenta" element={<Dashboard/>}/><Route path="/solicitudes" element={<Solicitudes/>}/><Route path="/solicitudes/nueva" element={<SolicitudForm/>}/><Route path="/solicitudes/:id/editar" element={<EditSolicitud/>}/><Route path="/comprobantes" element={<Comprobantes/>}/><Route path="/observaciones" element={<Observaciones/>}/><Route path="/atencion" element={<Atencion/>}/><Route path="/conexiones" element={<Private roles={['administrador']}><Conexiones/></Private>}/><Route path="/perfil" element={<Perfil/>}/><Route path="/fiscalizacion" element={<Private roles={['empleado','administrador']}><Fiscalizacion/></Private>}/><Route path="/usuarios" element={<Private roles={['administrador']}><Usuarios/></Private>}/><Route path="/auditoria" element={<Private roles={['administrador']}><Auditoria/></Private>}/></Route><Route path="/sunat/*" element={<Navigate to="/cuenta" replace/>}/><Route path="*" element={<Navigate to="/" replace/>}/></Routes></main>}<footer className="site-footer"><div className="container footer-top"><div><Link className="brand light" to="/"><Asset name="sunat-isotipo" alt="" className="brand-logo"/>SUNAT</Link><p>Más claridad en cada trámite.<br/>Más cerca de ti.</p></div><div><strong>Accesos rápidos</strong><Link to="/clave-sol">Clave SOL</Link><Link to="/solicitudes">Mis solicitudes</Link><Link to="/contacto">Atención digital</Link></div><div><strong>Tu espacio</strong><Link to="/login">Ingresar</Link><Link to="/como-funciona">Cómo solicitar</Link><Link to="/cronograma">Horarios de atención</Link></div></div><div className="container footer-bottom"><span>SUNAT Perú · Proyecto académico · Grupo 5</span><span>Johao Miguel Gavilán Erquinio</span></div></footer></>;}
function HeroGallery(){const [slide,setSlide]=useState(0),[paused,setPaused]=useState(false);const photos=[['hero-sunat','Sede de SUNAT Perú'],['sunat-digital','Servicios SUNAT desde tu computadora'],['sunat-atencion','Atención al contribuyente']];useEffect(()=>{if(paused||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const t=setInterval(()=>setSlide(v=>(v+1)%photos.length),6500);return()=>clearInterval(t);},[paused]);return <section className="hero hero-gallery"><MotionBackground/><div className="hero-stage" role="region" aria-label="Galería de SUNAT"><div className="hero-slides" style={{transform:'translateX(-'+slide*100+'%)'}}>{photos.map(([name,alt],i)=><div className={'hero-slide hero-slide-'+i} key={name} aria-hidden={slide!==i}><Asset name={name} alt={alt}/></div>)}</div><div className="hero-stage-shade"/><div className="container hero-grid"><div className="hero-copy"><span className="eyebrow light"><i/> SUNAT DIGITAL</span><h1>Tus trámites,<br/><em>más cerca.</em></h1><p>Solicita tu Clave SOL, sigue cada avance y gestiona tus servicios desde un solo lugar.</p><div className="hero-actions"><Link to="/solicitudes/nueva" className="btn btn-sunat">Solicitar Clave SOL <Icon name="arrow" size={18}/></Link><Link to="/como-funciona" className="btn btn-glass">Conoce los pasos</Link></div><div className="hero-trust"><Icon name="shield" size={17}/> Tu información, en un espacio protegido.</div></div><div className="hero-visual"><div className="floating-note note-status"><span className="note-icon"><Icon name="check"/></span><span><small>Tu próximo paso</small><strong>Solicitud de Clave SOL</strong></span></div><div className="floating-note note-security"><Icon name="shield" size={27}/><div><strong>Todo bajo control</strong><small>Consulta cada estado</small></div></div></div></div><div className="gallery-controls"><span className="gallery-count">0{slide+1}<i/>0{photos.length}</span><button aria-label="Foto anterior" onClick={()=>setSlide((slide+photos.length-1)%photos.length)}>←</button><div className="gallery-dots">{photos.map(([name],i)=><button key={name} aria-label={'Mostrar foto '+(i+1)} aria-pressed={slide===i} onClick={()=>setSlide(i)}><span/></button>)}</div><button aria-label="Foto siguiente" onClick={()=>setSlide((slide+1)%photos.length)}>→</button><button className="gallery-pause" aria-label={paused?'Reanudar galería':'Pausar galería'} onClick={()=>setPaused(!paused)}>{paused?'▶':'Ⅱ'}</button></div></div></section>;}
function Home(){return <><HeroGallery/><section className="quick-links"><div className="container row g-0 mx-auto">{[['key','Clave SOL','Inicia tu solicitud','/clave-sol'],['search','Mis solicitudes','Consulta tu seguimiento','/solicitudes'],['mail','Atención digital','Estamos para orientarte','/atencion']].filter(item=>item[3]!=='/conexiones'||rol(user)==='administrador').map(([icon,title,text,to])=><div className="col-md-4" key={title}><Link to={to}><Icon name={icon} size={28}/><span><strong>{title}</strong><small>{text}</small></span><Icon name="arrow" size={18}/></Link></div>)}</div></section><Guide/><section className="section section-soft home-benefits"><div className="container benefit-grid"><div className="benefit-image"><Asset name="hero-sunat" alt="Sede SUNAT"/><span className="image-corner"><Icon name="shield" size={32}/></span></div><div><span className="eyebrow">TU ESPACIO DIGITAL</span><h2>Menos vueltas.<br/>Más tranquilidad.</h2><p className="lead-copy">Tus solicitudes, comprobantes y comunicaciones organizados para que sepas siempre cuál es el siguiente paso.</p><ul className="check-list"><li><Icon name="check"/> Un código para seguir cada solicitud.</li><li><Icon name="check"/> Notas de revisión junto a tu trámite.</li><li><Icon name="check"/> Accesos según tu cuenta y tus permisos.</li></ul><Link className="text-link" to="/login">Descubre tu cuenta <Icon name="arrow" size={18}/></Link></div></div></section><section className="cta-band"><div className="container"><div><span className="eyebrow light">EMPIEZA HOY</span><h2>Da el primer paso.</h2><p>Tu siguiente trámite empieza con una cuenta.</p></div><Link to="/login?modo=registro" className="btn btn-white">Crear mi cuenta <Icon name="arrow" size={18}/></Link></div></section></>;}
function PublicTitle({tag,title,text}){return <section className="public-title"><MotionBackground/><div className="container"><span className="eyebrow light">{tag}</span><h1>{title}</h1><p>{text}</p></div></section>;}
function Services(){const {user}=useContext(Auth);return <><PublicTitle tag="SERVICIOS DIGITALES" title="Un portal. Todo más simple." text="Elige el servicio que necesitas y continúa desde tu cuenta."/><section className="section"><div className="container row g-4 mx-auto">{[['key','Solicitud de Clave SOL','Registra los datos del contribuyente y recibe un código para seguir tu trámite.','/solicitudes/nueva'],['search','Consulta y actualización','Revisa el estado de tus solicitudes y corrige las que todavía están registradas.','/solicitudes'],['document','Comprobantes','Consulta los comprobantes vinculados a las claves SOL de tu cuenta.','/comprobantes'],['shield','Sistemas conectados','Habilita un acceso temporal cuando tu solicitud esté aprobada.','/conexiones'],['mail','Atención digital','Envía una consulta y recibe la respuesta en tu cuenta.','/atencion'],['clock','Horario de atención','Conoce cómo se organiza la revisión de solicitudes.','/cronograma']].filter(item=>item[3]!=='/conexiones'||rol(user)==='administrador').map(([icon,title,text,to])=><div className="col-md-6 col-lg-4" key={title}><article className={"service-card service-card-"+icon}><ServiceArt kind={icon}/><h2>{title}</h2><p>{text}</p><Link to={to} className="text-link">Continuar <Icon name="arrow" size={18}/></Link></article></div>)}</div></section></>;}
function ClaveInfo(){return <><section className="sol-showcase"><MotionBackground/><div className="container sol-showcase-grid"><div><span className="eyebrow light">CLAVE SOL</span><h1>La llave de tu<br/><em>empresa digital.</em></h1><p>Solicita el acceso de tu empresa y sigue su revisión desde tu cuenta.</p><Link to="/solicitudes/nueva" className="btn btn-sunat">Iniciar solicitud <Icon name="arrow" size={18}/></Link></div><div className="sol-key-scene"><div className="sol-orbit orbit-a"/><div className="sol-orbit orbit-b"/><div className="sol-key-core"><Icon name="key" size={110}/></div><span className="sol-chip chip-empresa"><Icon name="user"/> Tu empresa</span><span className="sol-chip chip-documento"><Icon name="document"/> Comprobantes</span><span className="sol-chip chip-seguridad"><Icon name="shield"/> Acceso protegido</span></div></div></section><section className="section requirements-section"><div className="container"><div className="section-heading"><div><span className="eyebrow">ANTES DE EMPEZAR</span><h2>Lo esencial, a la mano.</h2></div><Link to="/como-funciona" className="text-link">Ver cómo solicitar <Icon name="arrow" size={18}/></Link></div><div className="requirements-grid">{[['document','Identifica tu empresa','Razón social y RUC de 11 dígitos.'],['user','Tu representante','El nombre de la persona que representa a tu empresa.'],['mail','Mantén el contacto','Un correo para consultar el avance de tu solicitud.']].map(([icon,title,text])=><article key={title}><span><Icon name={icon} size={30}/></span><h3>{title}</h3><p>{text}</p></article>)}</div><div className="sol-connection-strip"><div><Icon name="shield" size={35}/><span><strong>Una aprobación que te conecta.</strong><p>Cuando tu solicitud esté aprobada, podrás habilitar el acceso temporal a los servicios de comprobantes.</p></span></div><Link to="/solicitudes" className="btn btn-outline-sunat">Mis solicitudes <Icon name="arrow" size={16}/></Link></div></div></section></>;}
function StepArtFallback(){return <div className="key-floating" aria-hidden="true"><Icon name="key" size={70}/></div>;}
function GuidePage(){return <><PublicTitle tag="CÓMO SOLICITAR" title="Tu próximo paso, sin dudas." text="Explora cada etapa y descubre qué necesitas para continuar."/><SolJourney/><StateGuide/></>;}
function Agenda(){return <><PublicTitle tag="HORARIOS DE ATENCIÓN" title="Siempre sabes dónde estás." text="La revisión del portal se organiza en turnos. El estado de tu solicitud se actualiza desde tu cuenta."/><section className="section"><div className="container row g-4 mx-auto">{[['Mañana','06:00 – 14:00'],['Tarde','14:00 – 22:00'],['Noche','22:00 – 06:00']].map(([title,hour])=><div className="col-md-4" key={title}><article className="service-card"><Icon name="clock" size={35}/><h2>{title}</h2><p>{hour}</p><small>Hora de Lima · Sujeto al turno del trabajador asignado.</small></article></div>)}</div><div className="container mt-4"><Link to="/solicitudes" className="btn btn-sunat">Consultar mis solicitudes</Link></div></section></>;}
function Contact(){return <><PublicTitle tag="ATENCIÓN DIGITAL" title="Estamos para orientarte." text="Conserva tus consultas y respuestas en un solo lugar."/><section className="section"><div className="container benefit-grid"><div className="contact-photo"><Asset name="sunat-atencion" alt="Atención al contribuyente de SUNAT"/><span className="contact-photo-label"><Icon name="mail"/> Atención que te acompaña</span></div><div><span className="eyebrow">HABLEMOS</span><h2>Una respuesta,<br/>sin perder el hilo.</h2><p className="lead-copy">Entra a tu cuenta para enviar tu consulta y revisar la respuesta del equipo de atención.</p><Link to="/atencion" className="btn btn-sunat"><Icon name="mail" size={18}/> Enviar una consulta</Link><Link to="/como-funciona" className="text-link mt-4">Revisar la guía de solicitud <Icon name="arrow" size={18}/></Link></div></div></section></>;}
function Login(){const {user,setUser}=useContext(Auth);const [params]=useSearchParams();const [register,setRegister]=useState(params.get('modo')==='registro'),[form,setForm]=useState({nombre:'',correo:'',password:''}),[busy,setBusy]=useState(false),[error,setError]=useState('');const navigate=useNavigate();if(user)return <Navigate to="/cuenta" replace/>;async function submit(e){e.preventDefault();setBusy(true);setError('');try{const d=await api(register?'/auth/registro':'/auth/login','POST',form);setToken(d.token);setUser(d.user);navigate('/cuenta');}catch(e){setError(e.message);}finally{setBusy(false);}}const change=e=>setForm({...form,[e.target.name]:e.target.value});return <div className="auth-section"><div className="container auth-layout"><section className="auth-story"><Asset name="sunat-digital" alt="Servicios SUNAT en línea" className="auth-photo"/><MotionBackground/><div className="auth-story-content"><span className="eyebrow light">TU ESPACIO PERSONAL</span><h1>Tu espacio<br/>digital.</h1><p>Tus trámites y el siguiente paso, siempre contigo.</p><div className="auth-key"><Icon name="key" size={80}/></div><span className="auth-secure"><Icon name="shield" size={17}/> Acceso protegido</span></div></section><section className="auth-form"><span className="eyebrow">BIENVENIDO A SUNAT</span><h2>{register?'Crea tu cuenta':'Nos alegra verte.'}</h2><p>{register?'Empieza a gestionar tus trámites.':'Ingresa para continuar con tu cuenta.'}</p><ErrorMessage text={error}/><form onSubmit={submit}>{register&&<Field label="Nombre completo" name="nombre" value={form.nombre} onChange={change} minLength={3} maxLength={100}/>}<Field label="Correo electrónico" name="correo" type="email" autoComplete="username" value={form.correo} onChange={change}/><Field label="Contraseña" name="password" type="password" minLength={10} maxLength={100} autoComplete={register?'new-password':'current-password'} value={form.password} onChange={change}/>{register&&<small className="field-help">Usa al menos 10 caracteres.</small>}<button disabled={busy} className="btn btn-sunat w-100 mt-3">{busy?'Verificando…':register?'Crear mi cuenta':'Ingresar a mi cuenta'} <Icon name="arrow" size={18}/></button></form><button className="auth-toggle" onClick={()=>{setRegister(!register);setError('');}}>{register?'Ya tengo una cuenta':'¿Aún no tienes cuenta? Regístrate'}</button></section></div></div>;}
import {Outlet,useParams} from 'react-router-dom';
function AccountShell(){const {user,setUser}=useContext(Auth);const staff=isStaff(user);const nav=[['/cuenta','Resumen','chart'],['/solicitudes',staff?'Solicitudes':'Mis solicitudes','document'],...(!staff?[['/solicitudes/nueva','Nueva solicitud','key']]:[]),['/comprobantes','Comprobantes','document'],...(staff?[['/fiscalizacion','Fiscalización','chart']]:[]),['/observaciones','Observaciones','search'],['/atencion','Atención digital','mail'],...(rol(user)==='administrador'?[['/conexiones','Sistemas conectados','shield']]:[]),...(rol(user)==='administrador'?[['/usuarios','Usuarios y turnos','user'],['/auditoria','Actividad','clock']]:[]),['/perfil','Mi perfil','user']];return <div className="account-area"><div className="container account-grid"><aside className="account-sidebar"><div className="account-identity"><span className="avatar">{user.nombre.charAt(0)}</span><strong>{user.nombre}</strong><small>{rol(user)==='administrador'?'Jefatura':staff?'Trabajador':'Contribuyente'}</small></div><nav aria-label="Mi cuenta">{nav.map(([to,title,icon])=><NavLink key={to} to={to} end><Icon name={icon} size={18}/>{title}</NavLink>)}</nav><button className="logout" onClick={()=>{setToken(null);setUser(null);}}><Icon name="logout" size={17}/> Cerrar sesión</button></aside><div className="account-content"><Outlet/></div></div></div>;}
function Dashboard(){const {user}=useContext(Auth);const summary=useLoad('/resumen'),sol=useLoad('/solicitudes');return <><Title eyebrow={isStaff(user)?'ESPACIO DE GESTIÓN':'TU ESPACIO PERSONAL'} title={'Hola, '+user.nombre.split(' ')[0]+'.'} sub="Cada avance cuenta. Revisa lo importante y continúa con tu siguiente paso."/><Load state={summary}>{d=><div className="stat-grid">{[['Solicitudes',d.estados.reduce((n,s)=>n+s.total,0),'document'],['Aprobadas',d.estados.find(s=>s.estado==='aprobada')?.total||0,'check'],['Comprobantes',d.comprobantes,'shield']].map(([label,n,icon])=><div className="stat-card" key={label}><span><Icon name={icon} size={21}/></span><strong>{n}</strong><small>{label}</small></div>)}</div>}</Load><div className="account-banner"><div><span className="eyebrow light">{isStaff(user)?'CADA REVISIÓN IMPORTA':'TU SIGUIENTE PASO'}</span><h2>{isStaff(user)?'Una bandeja. Todo en orden.':'Tu Clave SOL empieza aquí.'}</h2><p>{isStaff(user)?'Revisa la información y acompaña al contribuyente.':'Registra los datos de tu empresa y recibe un código de seguimiento.'}</p><Link to={isStaff(user)?'/solicitudes':'/solicitudes/nueva'} className="btn btn-white">{isStaff(user)?'Revisar solicitudes':'Nueva solicitud'} <Icon name="arrow" size={17}/></Link></div><div className="banner-illustration" aria-hidden="true"><Icon name={isStaff(user)?'document':'key'} size={90}/><span><Icon name="check" size={22}/></span></div></div><section className="surface"><div className="surface-heading"><h2>Últimas solicitudes</h2><Link to="/solicitudes" className="text-link">Ver todas <Icon name="arrow" size={16}/></Link></div><Load state={sol}>{data=>data.length?<div className="recent-list">{data.slice(0,4).map(s=><Link to="/solicitudes" key={s.id}><span className="file-symbol"><Icon name="document"/></span><span><strong>{s.razon_social}</strong><small>{s.codigo_seguimiento} · {date(s.fecha_registro)}</small></span><Badge state={s.estado}/></Link>)}</div>:<Empty text="Tu primera solicitud aparecerá aquí."/>}</Load></section></>;}
const blankSol={razon_social:'',ruc:'',representante:'',correo:'',descripcion:''};
function RazonSocialField({form,setForm,empresas,loading}){const [otra,setOtra]=useState(false);const options=[...new Map(empresas.map(e=>[e.razon_social+'|'+e.ruc,e])).values()];const selected=options.find(e=>e.razon_social===form.razon_social&&e.ruc===form.ruc);const manual=otra||(!selected&&!!form.razon_social);return <Field label="Razón social" name="razon_social"><select id="field-razon_social" className="form-select" required value={manual?'otra':selected?selected.razon_social+'|'+selected.ruc:''} onChange={e=>{if(e.target.value==='otra'){setOtra(true);setForm(f=>({...f,razon_social:'',ruc:''}));}else{const item=options.find(x=>x.razon_social+'|'+x.ruc===e.target.value);setOtra(false);setForm(f=>({...f,razon_social:item?.razon_social||'',ruc:item?.ruc||''}));}}}><option value="" disabled>{loading?'Cargando empresas…':'Selecciona una razón social'}</option>{options.map(e=><option key={e.razon_social+'|'+e.ruc} value={e.razon_social+'|'+e.ruc}>{e.razon_social} · {e.ruc}</option>)}<option value="otra">Registrar otra razón social</option></select>{manual&&<div className="mt-3"><label htmlFor="field-nueva-razon-social">Nueva razón social</label><input id="field-nueva-razon-social" className="form-control" required minLength={3} maxLength={150} placeholder="Nombre de tu empresa" value={form.razon_social} onChange={e=>setForm(f=>({...f,razon_social:e.target.value}))}/></div>}</Field>;}
function SolicitudForm({initial=null,onSaved}){const {user}=useContext(Auth);const [form,setForm]=useState(initial||{...blankSol,representante:user.nombre,correo:user.correo}),[busy,setBusy]=useState(false),[error,setError]=useState(''),[success,setSuccess]=useState(null);const empresas=useLoad('/solicitudes');const users=useLoad(rol(user)==='administrador'?'/admin/usuarios':'/auth/me');const navigate=useNavigate();const change=e=>setForm({...form,[e.target.name]:e.target.value});async function submit(e){e.preventDefault();setBusy(true);setError('');setSuccess(null);try{const data=await api(initial?'/solicitudes/'+initial.id:'/solicitudes',initial?'PUT':'POST',{...form,...(form.id_usuario?{id_usuario:Number(form.id_usuario)}:{})});setSuccess(data);onSaved?.();}catch(e){setError(e.message);}finally{setBusy(false);}}return <><Title eyebrow="CLAVE SOL" title={initial?'Corrige tu solicitud.':'Un nuevo paso para tu empresa.'} sub="Completa los datos del contribuyente. Revisa la información antes de enviarla."/><div className="sol-form-grid"><section className="surface"><div className="surface-heading"><h2>Datos del contribuyente</h2><Icon name="shield" size={22}/></div><ErrorMessage text={error}/>{success?<div className="submission-result"><LetterFeedback state="success" code={success.codigo_seguimiento}/><p>{initial?'Los cambios quedaron guardados.':'Conserva este código para seguir el avance de tu solicitud.'}</p><Link to="/solicitudes" className="btn btn-sunat">Ver mis solicitudes <Icon name="arrow" size={18}/></Link><button className="btn btn-outline-sunat mt-2" onClick={()=>{setSuccess(null);setForm({...blankSol,representante:user.nombre,correo:user.correo});navigate('/solicitudes/nueva');}}>Nueva solicitud</button></div>:<form onSubmit={submit}>{rol(user)==='administrador'&&!initial&&Array.isArray(users.data)&&<Select label="Titular de la solicitud" name="id_usuario" value={form.id_usuario||user.id} onChange={change}>{users.data.filter(u=>u.activo).map(u=><option key={u.id} value={u.id}>{u.nombre} · {u.correo}</option>)}</Select>}<RazonSocialField form={form} setForm={setForm} empresas={(empresas.data||[]).filter(e=>e.id_usuario===Number(form.id_usuario||user.id))} loading={empresas.loading}/><div className="row g-3"><div className="col-md-6"><Field label="RUC" name="ruc" value={form.ruc} onChange={change} inputMode="numeric" pattern="[0-9]{11}" maxLength={11} placeholder="11 dígitos"/></div><div className="col-md-6"><Field label="Correo del contribuyente" name="correo" type="email" value={form.correo} onChange={change}/></div></div><Field label="Representante" name="representante" value={form.representante} onChange={change} minLength={3} maxLength={100}/><Field label="Motivo de la solicitud" name="descripcion"><textarea id="field-descripcion" className="form-control" name="descripcion" value={form.descripcion||''} onChange={change} rows={4} maxLength={2000} placeholder="Describe para qué necesitas tu Clave SOL; por ejemplo, emitir comprobantes o gestionar los trámites de tu empresa."/><small className="field-help">{(form.descripcion||'').length}/2000</small></Field><div className="form-actions"><Link to="/solicitudes" className="btn btn-outline-sunat">Volver</Link><button disabled={busy} className="btn btn-sunat">{busy?'Enviando…':initial?'Guardar cambios':'Enviar solicitud'} <Icon name="arrow" size={17}/></button></div></form>}</section><aside className="sol-form-aside">{busy?<LetterFeedback state="sending"/>:<><div className="aside-illustration"><Icon name="mail" size={76}/><span><Icon name="key" size={28}/></span></div><span className="eyebrow">ANTES DE ENVIAR</span><h2>Una buena revisión hace la diferencia.</h2><ul className="check-list"><li><Icon name="check"/> RUC de 11 dígitos.</li><li><Icon name="check"/> Nombre y razón social correctos.</li><li><Icon name="check"/> Correo de contacto actualizado.</li></ul><p>Podrás corregir tu solicitud mientras esté registrada.</p></>}</aside></div></>;}
function EditSolicitud(){const {id}=useParams(),state=useLoad('/solicitudes');return <Load state={state}>{data=>{const s=data.find(x=>x.id===Number(id));return s?<SolicitudForm initial={s}/>:<Empty text="Solicitud no encontrada."/>;}}</Load>;}
function Dialog({title,onClose,children}){const close=React.useRef(null);useEffect(()=>{const prev=document.activeElement,overflow=document.body.style.overflow;document.body.style.overflow='hidden';close.current?.focus();const key=e=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const nodes=close.current?.closest('[role=dialog]')?.querySelectorAll('button:not([disabled]),input,select,textarea,a[href]');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};window.addEventListener('keydown',key);return()=>{document.body.style.overflow=overflow;window.removeEventListener('keydown',key);prev?.focus?.();};},[onClose]);return <div className="dialog-backdrop" onClick={e=>e.target===e.currentTarget&&onClose()}><section className="dialog-card" role="dialog" aria-modal="true" aria-label={title}><div className="surface-heading"><h2>{title}</h2><button ref={close} className="close-dialog" aria-label="Cerrar" onClick={onClose}>×</button></div>{children}</section></div>;}
function Historial({sol}){const state=useLoad('/solicitudes/'+sol.id+'/historial');return <><div className="detail-summary"><Badge state={sol.estado}/><strong>{sol.codigo_seguimiento}</strong><p>{sol.razon_social} · {sol.ruc}</p><strong>Motivo de la solicitud</strong><p className="request-description">{sol.descripcion||'Sin descripción registrada.'}</p></div><Load state={state}>{rows=>rows.length?<ol className="timeline">{rows.map((h,i)=><li key={i}><span className="timeline-dot"/><strong>{h.accion}</strong><small>{date(h.fecha)} · {h.actor||'Sistema'}</small>{h.detalle?.nota&&<p>{h.detalle.nota}</p>}</li>)}</ol>:<p>Registrada el {date(sol.fecha_registro)}.</p>}</Load></>;}
function Solicitudes(){const {user}=useContext(Auth),state=useLoad('/solicitudes');const [query,setQuery]=useState(''),[filter,setFilter]=useState(''),[selected,setSelected]=useState(null),[mode,setMode]=useState(''),[error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[decision,setDecision]=useState('en proceso'),[nota,setNota]=useState('');const close=useCallback(()=>setSelected(null),[]);function open(s,m){setSelected(s);setMode(m);setDecision('en proceso');setNota('');setError('');}async function review(e){e.preventDefault();setBusy(true);setError('');try{await api('/solicitudes/'+selected.id+'/estado','PATCH',{estado:decision,nota});setSelected(null);setNotice('Estado actualizado.');state.reload();}catch(e){setError(e.message);}finally{setBusy(false);}}async function remove(){setBusy(true);setError('');try{await api('/solicitudes/'+selected.id,'DELETE');setSelected(null);setNotice('Solicitud retirada.');state.reload();}catch(e){setError(e.message);}finally{setBusy(false);}}return <><Title title={isStaff(user)?'Solicitudes de Clave SOL':'Mis solicitudes'} sub="Cada trámite, con su estado y su historia.">{rol(user)!=='empleado'&&<Link to="/solicitudes/nueva" className="btn btn-sunat">Nueva solicitud <Icon name="arrow" size={17}/></Link>}</Title><Notice text={notice}/>{!selected&&<ErrorMessage text={error}/>}<section className="surface"><div className="table-filters"><Field label="Buscar solicitud" name="busqueda" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Código, razón social o RUC" required={false}/><Select label="Estado" name="estado-filtro" value={filter} onChange={e=>setFilter(e.target.value)}><option value="">Todos los estados</option>{['registrado','en proceso','aprobada','rechazado'].map(s=><option key={s}>{s}</option>)}</Select></div><Load state={state}>{rows=>{const filtered=rows.filter(s=>(!filter||s.estado===filter)&&(s.codigo_seguimiento+' '+s.razon_social+' '+s.ruc).toLowerCase().includes(query.toLowerCase()));return filtered.length?<div className="table-responsive"><table className="table sunat-table"><thead><tr><th>Solicitud</th><th>Contribuyente</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{filtered.map(s=><tr key={s.id}><td><strong>{s.codigo_seguimiento}</strong><small>{date(s.fecha_registro)}</small></td><td><strong>{s.razon_social}</strong><small>{s.ruc}</small></td><td><Badge state={s.estado}/></td><td><div className="row-actions"><button className="btn btn-light btn-sm" onClick={()=>open(s,'historial')}>Ver</button>{(rol(user)==='administrador'||(!isStaff(user)&&s.estado==='registrado'))&&<Link className="btn btn-light btn-sm" to={'/solicitudes/'+s.id+'/editar'}>Editar</Link>}{isStaff(user)&&(rol(user)==='administrador'||['registrado','en proceso'].includes(s.estado))&&<button className="btn btn-outline-sunat btn-sm" onClick={()=>open(s,'revisar')}>Revisar</button>}{(rol(user)==='administrador'||(!isStaff(user)&&s.estado==='registrado'))&&<button className="btn btn-danger-soft btn-sm" onClick={()=>open(s,'retirar')}>Retirar</button>}</div></td></tr>)}</tbody></table></div>:<Empty text="No hay solicitudes para esta búsqueda."/>;}}</Load></section>{selected&&<Dialog title={mode==='historial'?'Seguimiento de solicitud':mode==='revisar'?'Revisar solicitud':'Retirar solicitud'} onClose={close}><ErrorMessage text={error}/>{mode==='historial'?<Historial sol={selected}/>:mode==='revisar'?<form onSubmit={review}><div className="detail-summary"><strong>{selected.razon_social}</strong><p>{selected.ruc} · {selected.codigo_seguimiento}</p><p>{selected.representante} · {selected.correo}</p><Badge state={selected.estado}/><strong>Motivo de la solicitud</strong><p className="request-description">{selected.descripcion||'Sin descripción registrada.'}</p></div><Select label="Nuevo estado" name="decision" value={decision} onChange={e=>setDecision(e.target.value)}>{['en proceso','aprobada','rechazado'].map(x=><option key={x}>{x}</option>)}</Select><Field label="Observación de revisión" name="nota"><textarea className="form-control" id="field-nota" value={nota} onChange={e=>setNota(e.target.value)} maxLength={1000} rows={3}/></Field><button disabled={busy} className="btn btn-sunat w-100">{busy?'Guardando…':'Guardar revisión'}</button></form>:<><p>¿Quieres retirar la solicitud <strong>{selected.codigo_seguimiento}</strong>?</p><p>Se conservará su historial de actividad.</p><button disabled={busy} className="btn btn-danger" onClick={remove}>{busy?'Retirando…':'Sí, retirar solicitud'}</button></>}</Dialog>}</>;}
function Comprobantes(){const state=useLoad('/comprobantes'),[q,setQ]=useState('');return <><Title eyebrow="COMPROBANTES" title="Todo lo recibido, en orden." sub="Boletas y facturas vinculadas a solicitudes aprobadas."/><section className="surface"><Field label="Buscar comprobante" name="buscar-comprobante" value={q} onChange={e=>setQ(e.target.value)} placeholder="Número, RUC o contribuyente" required={false}/><Load state={state}>{rows=>{const data=rows.filter(r=>(r.numero_comprobante+' '+r.ruc+' '+r.razon_social).toLowerCase().includes(q.toLowerCase()));return data.length?<><div className="table-responsive"><table className="table sunat-table"><thead><tr><th>Comprobante</th><th>Emisor</th><th>Documento</th><th>Monto</th><th>Estado</th></tr></thead><tbody>{data.map(r=><tr key={r.id}><td><strong>{r.numero_comprobante}</strong><small>{date(r.fecha)}</small></td><td><strong>{r.razon_social}</strong><small>{r.ruc}</small></td><td>{r.doc_cliente}<small>{r.tipo_comprobante}</small></td><td>{money(r.monto)}</td><td><Badge state={r.estado}/></td></tr>)}</tbody></table></div><button className="btn btn-outline-sunat no-print" onClick={()=>window.print()}>Imprimir consulta</button></>:<Empty text="Todavía no hay comprobantes vinculados."/>;}}</Load></section></>;}
function Fiscalizacion(){const state=useLoad('/fiscalizacion');return <><Title eyebrow="FISCALIZACIÓN" title="Una mirada a las ventas." sub="Consulta los totales por contribuyente a partir de los comprobantes vinculados."/><Load state={state}>{rows=><><div className="total-banner"><div><span>Total vendido</span><strong>{money(rows.reduce((n,r)=>n+Number(r.total),0))}</strong></div><div><strong>{rows.reduce((n,r)=>n+r.comprobantes,0)}</strong><span>comprobantes</span></div></div><section className="surface"><h2>Ventas por contribuyente</h2>{rows.length?<div className="sales-ranking">{rows.map(r=><div className="sales-row" key={r.ruc+r.razon_social}><div><strong>{r.razon_social}</strong><small>RUC {r.ruc} · {r.comprobantes} comprobantes</small><div className="sales-track"><span style={{width:Math.max(2,Number(r.total)/Math.max(1,...rows.map(r=>Number(r.total)))*100)+'%'}}/></div></div><strong>{money(r.total)}</strong></div>)}</div>:<Empty/>}</section></>}</Load></>;}
function Observaciones(){const {user}=useContext(Auth),state=useLoad('/observaciones'),sol=useLoad('/solicitudes');const [form,setForm]=useState({id_clave_sol:'',detalle:''}),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');async function submit(e){e.preventDefault();setBusy(true);setError('');try{await api('/observaciones','POST',{...form,id_clave_sol:Number(form.id_clave_sol)});setNotice('Observación registrada.');setForm({...form,detalle:''});state.reload();}catch(e){setError(e.message);}finally{setBusy(false);}}return <><Title title="Observaciones" sub="Las notas de revisión siempre junto a tu solicitud."/><Notice text={notice}/><ErrorMessage text={error}/>{isStaff(user)&&<section className="surface mb-4"><h2>Registrar observación</h2><form onSubmit={submit}><Select label="Solicitud" name="id_clave_sol" required value={form.id_clave_sol} onChange={e=>setForm({...form,id_clave_sol:e.target.value})}><option value="">Selecciona una solicitud</option>{sol.data?.map(s=><option key={s.id} value={s.id}>{s.codigo_seguimiento} · {s.razon_social}</option>)}</Select><Field label="Observación" name="detalle"><textarea id="field-detalle" className="form-control" required minLength={5} maxLength={2000} rows={3} value={form.detalle} onChange={e=>setForm({...form,detalle:e.target.value})}/></Field><button className="btn btn-sunat" disabled={busy}>{busy?'Guardando…':'Guardar observación'}</button></form></section>}<Load state={state}>{rows=>rows.length?<div className="notes-list">{rows.map(o=><article className="surface note-card" key={o.id}><span className="note-marker"><Icon name="document"/></span><div><small>{o.codigo_seguimiento} · {date(o.fecha)}</small><h2>{o.razon_social}</h2><p>{o.detalle}</p><small>{o.autor}</small></div></article>)}</div>:<Empty text="No tienes observaciones pendientes de lectura."/>}</Load></>;}
function Atencion(){const {user}=useContext(Auth),state=useLoad('/atencion');const [form,setForm]=useState({asunto:'',mensaje:''}),[selected,setSelected]=useState(null),[respuesta,setRespuesta]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');const close=useCallback(()=>setSelected(null),[]);async function submit(e){e.preventDefault();setBusy(true);setError('');try{if(selected){await api('/atencion/'+selected.id,'PATCH',{respuesta});setSelected(null);}else{await api('/atencion','POST',form);setForm({asunto:'',mensaje:''});}setNotice(selected?'Respuesta enviada.':'Consulta recibida.');state.reload();}catch(e){setError(e.message);}finally{setBusy(false);}}return <><Title title="Atención digital" sub="Un espacio para consultar y continuar la conversación."/><Notice text={notice}/>{!selected&&<ErrorMessage text={error}/>}<section className="surface mb-4"><h2>Nueva consulta</h2><form onSubmit={submit}><Field label="Asunto" name="asunto" value={form.asunto} onChange={e=>setForm({...form,asunto:e.target.value})} minLength={3} maxLength={150}/><Field label="Consulta" name="mensaje"><textarea id="field-mensaje" className="form-control" required rows={3} minLength={10} maxLength={3000} value={form.mensaje} onChange={e=>setForm({...form,mensaje:e.target.value})}/></Field><button className="btn btn-sunat" disabled={busy}><Icon name="mail" size={18}/>{busy?'Enviando…':'Enviar consulta'}</button></form></section><Load state={state}>{rows=>rows.length?<div className="notes-list">{rows.map(c=><article className="surface" key={c.id}><div className="surface-heading"><div><small>ATE-{String(c.id).padStart(6,'0')} · {date(c.creado_en)}</small><h2>{c.asunto}</h2></div><Badge state={c.respuesta?'respondida':'pendiente'}/></div><p>{c.mensaje}</p>{isStaff(user)&&<small>{c.nombre} · {c.correo}</small>}{c.respuesta&&<div className="support-answer"><strong>Respuesta del equipo</strong><p>{c.respuesta}</p><small>{date(c.respondido_en)}</small></div>}{isStaff(user)&&<button className="btn btn-outline-sunat mt-3" onClick={()=>{setSelected(c);setRespuesta(c.respuesta||'');}}>Responder</button>}</article>)}</div>:<Empty text="Tus consultas aparecerán aquí."/>}</Load>{selected&&<Dialog title={'Responder: '+selected.asunto} onClose={close}><ErrorMessage text={error}/><form onSubmit={submit}><p>{selected.mensaje}</p><Field label="Respuesta" name="respuesta"><textarea id="field-respuesta" className="form-control" required rows={4} minLength={5} maxLength={3000} value={respuesta} onChange={e=>setRespuesta(e.target.value)}/></Field><button disabled={busy} className="btn btn-sunat">{busy?'Enviando…':'Enviar respuesta'}</button></form></Dialog>}</>;}
function Conexiones(){const state=useLoad('/solicitudes'),tokens=useLoad('/integracion/tokens');const [sid,setSid]=useState(''),[result,setResult]=useState(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[copied,setCopied]=useState(false);async function generate(e){e.preventDefault();setBusy(true);setError('');setResult(null);try{setResult(await api('/integracion/token','POST',{id_clave_sol:Number(sid)}));tokens.reload();}catch(e){setError(e.message);}finally{setBusy(false);}}async function revoke(jti){try{await api('/integracion/tokens/'+jti,'DELETE');if(result?.jti===jti)setResult(null);tokens.reload();}catch(e){setError(e.message);}}return <><Title title="Sistemas conectados" sub="Autoriza la conexión de una empresa con una solicitud aprobada."/><ErrorMessage text={error}/><section className="surface mb-4"><div className="connection-illustration" aria-hidden="true"><Icon name="key" size={38}/><span/><Icon name="shield" size={42}/><span/><Icon name="document" size={38}/></div><h2>Un acceso, bajo tu control.</h2><p>El acceso es válido durante 15 minutos. Puedes revocarlo cuando lo necesites.</p><Load state={state}>{rows=>{const own=rows.filter(s=>s.estado==='aprobada');return own.length?<form onSubmit={generate}><Select label="Clave SOL aprobada" name="clave-conexion" required value={sid} onChange={e=>setSid(e.target.value)}><option value="">Selecciona tu contribuyente</option>{own.map(s=><option key={s.id} value={s.id}>{s.razon_social} · {s.ruc}</option>)}</Select><button className="btn btn-sunat" disabled={busy}>{busy?'Habilitando…':'Generar acceso temporal'}</button></form>:<Empty text="Cuando tu solicitud esté aprobada podrás habilitar una conexión."/>;}}</Load>{result&&<div className="access-result"><strong>Acceso generado</strong><p>Vence: {date(result.expira_en)}. Compártelo únicamente con el sistema que vas a conectar.</p><label htmlFor="access-token">Token temporal</label><textarea id="access-token" className="form-control" readOnly value={result.token} rows={3}/><button className="btn btn-outline-sunat mt-2" onClick={async()=>{try{await navigator.clipboard.writeText(result.token);setCopied(true);}catch{setError('Selecciona el token y cópialo manualmente.');}}}>{copied?'Copiado':'Copiar token'}</button></div>}</section><section className="surface"><h2>Accesos recientes</h2><Load state={tokens}>{rows=>rows.length?<div className="token-list">{rows.map(t=><div key={t.jti}><span><strong>Clave SOL #{t.id_clave_sol}</strong><small>Vence {date(t.expira_en)}</small></span><Badge state={t.revocado?'revocado':new Date(t.expira_en)<new Date()?'vencido':'activo'}/>{!t.revocado&&new Date(t.expira_en)>new Date()&&<button className="btn btn-danger-soft btn-sm" onClick={()=>revoke(t.jti)}>Revocar</button>}</div>)}</div>:<Empty/>}</Load></section></>;}
function Perfil(){const {user,setUser}=useContext(Auth);const [form,setForm]=useState({nombre:user.nombre,correo:user.correo,actual:'',nueva:''}),[error,setError]=useState(''),[busy,setBusy]=useState(false);const change=e=>setForm({...form,[e.target.name]:e.target.value});async function submit(e){e.preventDefault();setBusy(true);setError('');try{await api('/perfil','PUT',{...form,nueva:form.nueva||undefined});setToken(null);setUser(null);}catch(e){setError(e.message);setBusy(false);}}return <><Title title="Mi perfil" sub="Mantén tus datos de acceso actualizados."/><section className="surface"><ErrorMessage text={error}/><form onSubmit={submit}><Field label="Nombre completo" name="nombre" value={form.nombre} onChange={change} minLength={3}/><Field label="Correo electrónico" name="correo" type="email" value={form.correo} onChange={change}/><Field label="Contraseña actual" name="actual" type="password" value={form.actual} onChange={change} autoComplete="current-password"/><Field label="Nueva contraseña (opcional)" name="nueva" type="password" value={form.nueva} onChange={change} required={false} minLength={10} maxLength={100} autoComplete="new-password"/><p className="field-help">Al guardar, vuelve a iniciar sesión con tus datos actualizados.</p><button className="btn btn-sunat" disabled={busy}>{busy?'Guardando…':'Guardar cambios'}</button></form></section></>;}
const emptyUser={nombre:'',correo:'',rol:'cliente',activo:true,password:'',turno_nombre:'Completo',turno_inicio:'00:00',turno_fin:'23:59'};
function Usuarios(){const state=useLoad('/admin/usuarios');const [editing,setEditing]=useState(null),[form,setForm]=useState(emptyUser),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');const close=useCallback(()=>setEditing(null),[]);const change=e=>setForm({...form,[e.target.name]:e.target.type==='checkbox'?e.target.checked:e.target.value});async function submit(e){e.preventDefault();setBusy(true);setError('');try{await api('/admin/usuarios'+(editing.id?'/'+editing.id:''),editing.id?'PUT':'POST',{...form,password:form.password||undefined,turno_nombre:form.rol==='empleado'?form.turno_nombre:null,turno_inicio:form.rol==='empleado'?form.turno_inicio:null,turno_fin:form.rol==='empleado'?form.turno_fin:null});setEditing(null);setNotice('Cuenta guardada.');state.reload();}catch(e){setError(e.message);}finally{setBusy(false);}}return <><Title eyebrow="JEFATURA" title="Usuarios y turnos" sub="Administra el acceso de contribuyentes y trabajadores."><button className="btn btn-sunat" onClick={()=>{setEditing({});setForm(emptyUser);setError('');}}>Nueva cuenta</button></Title><Notice text={notice}/><section className="surface"><Load state={state}>{rows=><div className="table-responsive"><table className="table sunat-table"><thead><tr><th>Cuenta</th><th>Rol</th><th>Turno</th><th>Estado</th><th/></tr></thead><tbody>{rows.map(u=><tr key={u.id}><td><strong>{u.nombre}</strong><small>{u.correo}</small></td><td>{u.rol}</td><td>{u.rol==='empleado'?<>{u.turno_nombre}<small>{String(u.turno_inicio||'').slice(0,5)} – {String(u.turno_fin||'').slice(0,5)}</small></>:'—'}</td><td><Badge state={u.activo?'activo':'inactivo'}/></td><td><button className="btn btn-light btn-sm" onClick={()=>{setEditing(u);setForm({...emptyUser,...u,password:'',turno_inicio:String(u.turno_inicio||'00:00').slice(0,5),turno_fin:String(u.turno_fin||'23:59').slice(0,5),turno_nombre:u.turno_nombre||'Completo'});setError('');}}>Editar</button></td></tr>)}</tbody></table></div>}</Load></section>{editing&&<Dialog title={editing.id?'Editar cuenta':'Nueva cuenta'} onClose={close}><ErrorMessage text={error}/><form onSubmit={submit}><Field label="Nombre" name="nombre" value={form.nombre} onChange={change} minLength={3}/><Field label="Correo" name="correo" type="email" value={form.correo} onChange={change}/><Select label="Rol SUNAT" name="rol" value={form.rol} onChange={change}>{['cliente','empleado','administrador'].map(r=><option key={r}>{r}</option>)}</Select><Field label={editing.id?'Nueva contraseña (opcional)':'Contraseña inicial'} name="password" type="password" value={form.password} onChange={change} required={!editing.id} minLength={10} maxLength={100} autoComplete="new-password"/>{form.rol==='empleado'&&<><Select label="Turno" name="turno_nombre" value={form.turno_nombre} onChange={e=>{const turnos={Mañana:['06:00','14:00'],Tarde:['14:00','22:00'],Noche:['22:00','06:00'],Completo:['00:00','23:59']};const [a,b]=turnos[e.target.value]||[form.turno_inicio,form.turno_fin];setForm({...form,turno_nombre:e.target.value,turno_inicio:a,turno_fin:b});}}>{['Completo','Mañana','Tarde','Noche','Personalizado'].map(t=><option key={t}>{t}</option>)}</Select><div className="row g-3"><div className="col-6"><Field label="Inicio del turno" name="turno_inicio" type="time" value={form.turno_inicio} onChange={change}/></div><div className="col-6"><Field label="Fin del turno" name="turno_fin" type="time" value={form.turno_fin} onChange={change}/></div></div><small className="field-help">Hora de Lima.</small></>}<label className="checkbox-label"><input name="activo" type="checkbox" checked={form.activo} onChange={change}/> Cuenta activa</label><button disabled={busy} className="btn btn-sunat w-100">{busy?'Guardando…':'Guardar cuenta'}</button></form></Dialog>}</>;}
function Auditoria(){const state=useLoad('/admin/auditoria');return <><Title eyebrow="JEFATURA" title="Actividad del sistema" sub="Consulta las acciones registradas y sus responsables."/><section className="surface"><Load state={state}>{rows=><div className="table-responsive"><table className="table sunat-table"><thead><tr><th>Fecha</th><th>Responsable</th><th>Acción</th><th>Registro</th></tr></thead><tbody>{rows.map(a=><tr key={a.id}><td>{date(a.fecha)}</td><td>{a.actor||'Sistema'}</td><td>{a.accion}</td><td>{a.entidad} #{a.entidad_id}</td></tr>)}</tbody></table></div>}</Load></section></>;}
